const loadSavedBalanceSettings = () => {
  if (typeof window === "undefined") return BALANCE;
  try {
    const raw = window.localStorage.getItem(BALANCE_STORAGE_KEY);
    if (!raw) return BALANCE;
    return mergeBalanceSettings(BALANCE, JSON.parse(raw));
  } catch {
    return BALANCE;
  }
};

