const EIGHT_BALL_SILHOUETTE_URI = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(EIGHT_BALL_SILHOUETTE_SVG)}`;
const isWreckerJumpInvulnerable = (ball) => (ball?.type === "wrecker" && ["charging", "swinging", "rage_charging", "rage_dashing", "rage_slamming"].includes(ball.wreckerState)) || (ball?.type === "dragon" && ball.dragonState === "dashing");
const isEightBallBreakInvulnerable = (ball, currentTime) => false;
const isBomberSelfDestructInvulnerable = (ball) => false;

const interruptSkills = (ball) => {
  if (!ball) return;
  if (ball.laserState) ball.laserState = "idle";
  if (ball.laserStateUntil) ball.laserStateUntil = 0;
  if (ball.hammerState) ball.hammerState = "spinning";
  if (ball.hammerStateUntil) ball.hammerStateUntil = 0;
  if (ball.dragonBreathUntil) ball.dragonBreathUntil = 0;
  if (ball.knifeBladeState && ball.knifeBladeState !== "rotating") ball.knifeBladeState = "rotating";
  if (ball.tridentDiveState && ball.tridentDiveState !== "idle") ball.tridentDiveState = "idle";
  if (ball.type === "shield" && (ball.shieldState === "held" || ball.shieldState === "windup")) {
    ball.shieldState = "held";
    ball.shieldGuardHits = 0;
    ball.shieldX = ball.x + Math.cos(ball.shieldAngle || 0) * (ball.r + 8);
    ball.shieldY = ball.y + Math.sin(ball.shieldAngle || 0) * (ball.r + 8);
    ball.shieldVx = 0;
    ball.shieldVy = 0;
    ball.shieldThrownUntil = 0;
    ball.shieldNextHitAt = 0;
    ball.shieldSpinAngle = 0;
    ball.shieldBonusDamage = 0;
    ball.shieldLaserPierceHits = 0;
  }
};

const isGrabInvulnerable = (ball, currentTime) => {
  if (!ball) return false;
  if (ball.type === "wrecker" && ["charging", "swinging", "rage_charging", "rage_dashing", "rage_slamming"].includes(ball.wreckerState)) return true;
  if (ball.type === "dragon" && ball.dragonState === "dashing") return true;
  if (ball.type === "shield" && ball.shieldBashUntil && currentTime < ball.shieldBashUntil) return true;
  if (ball.type === "hammer" && (ball.hammerState === "charging" || ball.hammerState === "launching")) return true;
  return false;
};

const cancelActiveMovementStates = (ball) => {
  if (!ball) return;
  if (ball.type === "wrecker" && ["charging", "swinging", "rage_charging", "rage_dashing", "rage_slamming"].includes(ball.wreckerState)) {
    ball.wreckerState = "normal";
    ball.wreckerGrabbedTargetId = null;
    ball.wreckerStateUntil = 0;
  }
  if (ball.shieldBashUntil) {
    ball.shieldBashUntil = 0;
  }
  if (ball.hammerState === "launching" || ball.hammerState === "charging") {
    ball.hammerState = "spinning";
    ball.hammerStateUntil = 0;
  }
  if (ball.type === "batter" && (ball.batterState === "charging" || ball.batterState === "swinging")) {
    ball.batterState = "idle";
    ball.batterStateUntil = 0;
    ball.batterSwingHit = false;
  }
  if (ball.dragonState === "dashing") {
    ball.dragonState = "idle";
    ball.dragonBreathUntil = 0;
  }
  if (ball.tridentDiveState && ball.tridentDiveState !== "idle") {
    ball.tridentDiveState = "idle";
    ball.tridentDiveHitDone = false;
  }
  if (ball.type === "feralClaw" && ball.feralPounceUntil) {
    ball.feralPounceUntil = 0;
    ball.feralPounceHit = false;
    ball.feralPounceState = "idle";
    ball.feralPounceWindupUntil = 0;
    ball.feralPounceSettleUntil = 0;
  }
  if (ball.armState === "elbow_dropping") {
    ball.armState = "idle";
    ball.armStateUntil = 0;
  }
  if (ball.type === "spider") {
    ball.webState = "idle";
    ball.webTargetId = null;
    ball.webBouncesLeft = 0;
    ball.webStateUntil = 0;
    ball.webVx = 0;
    ball.webVy = 0;
    ball.bsSkillState = "idle";
    ball.bsHookedTargetId = null;
    ball.bsPullUntil = 0;
    ball.bsSpinUntil = 0;
    ball.bsStringVx = 0;
    ball.bsStringVy = 0;
  }
};

const applyMotorcycleRagdoll = (ball, angle, force, currentTime, lockDuration = 1400, additive = true) => {
  if (!ball) return;
  cancelActiveMovementStates(ball);
  const launchVx = Math.cos(angle) * force;
  const launchVy = Math.sin(angle) * force;
  ball.vx = additive ? (ball.vx || 0) + launchVx : launchVx + (ball.vx || 0) * 0.18;
  ball.vy = additive ? (ball.vy || 0) + launchVy : launchVy + (ball.vy || 0) * 0.18;
  ball.skillLockedUntil = Math.max(ball.skillLockedUntil || 0, currentTime + lockDuration);
  ball.ragdollUntil = Math.max(ball.ragdollUntil || 0, currentTime + lockDuration);
  const tumbleDirection = Math.sin(angle * 1.7 + currentTime * 0.013) >= 0 ? 1 : -1;
  ball.ragdollSpinVelocity = tumbleDirection * (20 + Math.min(12, force / 120));
};

const isBallConnected = (ball, balls = [], currentTime = 0) => {
  if (!ball) return false;
  if (ball.type === "vampire" && ball.latchedTo && ball.latchUntil > currentTime) return true;
  if (ball.type === "spider" && (ball.webState === "pulling" || ball.webState === "webBouncing")) return true;
  if (ball.type === "arm" && ball.armState === "elbow_dropping" && ball.armStateUntil > currentTime) return true;
  if (ball.type === "hammer" && ball.hammerState === "charging") return true;
  if (ball.type === "wrecker" && ["charging", "swinging"].includes(ball.wreckerState)) return true;
  if (ball.jokerPulledUntil && ball.jokerPulledUntil > currentTime) return true;
  if (ball.tridentPinnedUntil && ball.tridentPinnedUntil > currentTime) return true;
  if ((ball.type === "blackSpider" || ball.type === "spider") && ball.bsSkillState && ball.bsSkillState !== "idle") return true;

  return balls.some((other) => {
    if (!other || other.id === ball.id) return false;
    if (other.type === "vampire" && other.latchedTo === ball.id && other.latchUntil > currentTime) return true;
    if (other.type === "spider" && other.webTargetId === ball.id && (other.webState === "pulling" || other.webState === "webBouncing")) return true;
    if (other.type === "arm" && other.armGrabTargetId === ball.id && other.armState === "elbow_dropping" && other.armStateUntil > currentTime) return true;
    if (other.type === "joker" && other.jokerPullTargetId === ball.id && other.jokerPullUntil > currentTime) return true;
    if (other.tridentTargetId === ball.id && (other.tridentState === "thrown" || other.tridentState === "stuck")) return true;
    if (other.type === "wrecker" && other.wreckerActionTargetId === ball.id && ["swinging"].includes(other.wreckerState)) return true;
    if ((other.type === "blackSpider" || other.type === "spider") && other.bsHookedTargetId === ball.id && (other.bsSkillState === "pulling" || other.bsSkillState === "spinning")) return true;
    return false;
  });
};

const canStartSkillConnection = (actor, target, balls, currentTime) => (
  !isBallConnected(actor, balls, currentTime) && 
  !isBallConnected(target, balls, currentTime) &&
  (!target.attachmentResistanceUntil || target.attachmentResistanceUntil <= currentTime) &&
  !isGrabInvulnerable(target, currentTime)
);

const linePointDist = (px, py, x1, y1, x2, y2) => {
  const A = px - x1, B = py - y1, C = x2 - x1, D = y2 - y1;
  const dot = A * C + B * D, lenSq = C * C + D * D;
  let param = -1;
  if (lenSq !== 0) param = dot / lenSq;
  let xx, yy;
  if (param < 0) { xx = x1; yy = y1; }
  else if (param > 1) { xx = x2; yy = y2; }
  else { xx = x1 + param * C; yy = y1 + param * D; }
  return Math.hypot(px - xx, py - yy);
};

const segmentSegmentDist = (a1x, a1y, a2x, a2y, b1x, b1y, b2x, b2y) => {
  const orient = (ax, ay, bx, by, cx, cy) => (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
  const between = (a, b, c) => Math.min(a, b) <= c + 0.001 && c <= Math.max(a, b) + 0.001;
  const o1 = orient(a1x, a1y, a2x, a2y, b1x, b1y);
  const o2 = orient(a1x, a1y, a2x, a2y, b2x, b2y);
  const o3 = orient(b1x, b1y, b2x, b2y, a1x, a1y);
  const o4 = orient(b1x, b1y, b2x, b2y, a2x, a2y);
  const crosses = ((o1 > 0 && o2 < 0) || (o1 < 0 && o2 > 0)) && ((o3 > 0 && o4 < 0) || (o3 < 0 && o4 > 0));
  const touches =
    (Math.abs(o1) < 0.001 && between(a1x, a2x, b1x) && between(a1y, a2y, b1y)) ||
    (Math.abs(o2) < 0.001 && between(a1x, a2x, b2x) && between(a1y, a2y, b2y)) ||
    (Math.abs(o3) < 0.001 && between(b1x, b2x, a1x) && between(b1y, b2y, a1y)) ||
    (Math.abs(o4) < 0.001 && between(b1x, b2x, a2x) && between(b1y, b2y, a2y));
  if (crosses || touches) return 0;
  return Math.min(
    linePointDist(a1x, a1y, b1x, b1y, b2x, b2y),
    linePointDist(a2x, a2y, b1x, b1y, b2x, b2y),
    linePointDist(b1x, b1y, a1x, a1y, a2x, a2y),
    linePointDist(b2x, b2y, a1x, a1y, a2x, a2y)
  );
};

const isLineWrappingCorner = (x1, y1, x2, y2, cx, cy, threshold = 28) => {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const lenSq = dx * dx + dy * dy;
  if (lenSq < 1) return false;
  
  const dot1 = (cx - x1) * dx + (cy - y1) * dy;
  if (dot1 < 0) return false;
  const dot2 = (cx - x2) * (-dx) + (cy - y2) * (-dy);
  if (dot2 < 0) return false;
  
  const dist = linePointDist(cx, cy, x1, y1, x2, y2);
  return dist < threshold;
};

const getStringBounceVelocity = (ball, str, hitX, hitY, speed, seed = 0) => {
  const dx = str.x2 - str.x1;
  const dy = str.y2 - str.y1;
  const len = Math.hypot(dx, dy) || 1;
  const tx = dx / len;
  const ty = dy / len;
  const nx = -ty;
  const ny = tx;
  const side = Math.sign((ball.x - hitX) * nx + (ball.y - hitY) * ny) || Math.sign(ball.vx * nx + ball.vy * ny) || 1;
  const travel = Math.sign(ball.vx * tx + ball.vy * ty) || (Math.sin(seed * 0.017) > 0 ? 1 : -1);
  const wobble = Math.sin(seed * 0.031 + ball.id.length) * 0.16;
  let outX = nx * side * 0.78 + tx * travel * (0.42 + wobble);
  let outY = ny * side * 0.78 + ty * travel * (0.42 + wobble);
  let outLen = Math.hypot(outX, outY) || 1;
  outX /= outLen;
  outY /= outLen;

  if (Math.abs(outX * tx + outY * ty) > 0.82) {
    outX = nx * side * 0.88 + tx * travel * 0.28;
    outY = ny * side * 0.88 + ty * travel * 0.28;
    outLen = Math.hypot(outX, outY) || 1;
    outX /= outLen;
    outY /= outLen;
  }

  return { vx: outX * speed, vy: outY * speed };
};

const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
const distance = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
const isChessCrownActive = (ball) => ball?.type === "chess" && (
  ball.chessState === "movingToCenter" ||
  ball.chessState === "activeCrown" ||
  ball.chessState === "attacking"
);

const drawStar = (ctx, cx, cy, spikes, outerRadius, innerRadius) => {
  let rot = (Math.PI / 2) * 3;
  let x;
  let y;
  const step = Math.PI / spikes;
  ctx.beginPath();
  ctx.moveTo(cx, cy - outerRadius);
  for (let i = 0; i < spikes; i++) {
    x = cx + Math.cos(rot) * outerRadius;
    y = cy + Math.sin(rot) * outerRadius;
    ctx.lineTo(x, y);
    rot += step;
    x = cx + Math.cos(rot) * innerRadius;
    y = cy + Math.sin(rot) * innerRadius;
    ctx.lineTo(x, y);
    rot += step;
  }
  ctx.lineTo(cx, cy - outerRadius);
  ctx.closePath();
  ctx.fillStyle = "#ffffff";
  ctx.fill();
};

const StaticBallCanvas = ({ type, color, stroke, drawBallProxyRef, proxyReady }) => {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    
    const ballRadius = BALL_TYPES[type]?.radius || 28;
    const mockBall = {
      id: "mock-" + type,
      type: type,
      x: 48, // centered in 96x96 canvas
      y: 48,
      r: ballRadius,
      health: 100,
      angle: 0, // facing right (1st player start)
      spinAngle: 0,
      side: "left",
      
      // Default properties to prevent any issues with specific rendering types
      knifeBladeState: "rotating",
      saberSlashActive: false,
      fireSwordState: "idle",
      fireSwordSwingAngle: 0,
      wreckerState: "idle",
      flashUntil: 0,
      dog: null,
      latchUntil: 0,
      shieldActive: false,
      webState: "idle",
      hammerState: "idle",
      chessRole: "pawn",
      
      // Black Spider
      bsSkillState: "idle",
      bsHookedTargetId: null,
      
      // Feral Claw
      feralComboStage: 0,
      
      // Joker
      jokerFlashUntil: 0,

      // Fisherman
      fishermanPulledUntil: 0,
      fishermanPullOwnerId: null,
      
      // Gazer
      gazerAuraActive: false,
      laserTargetAngle: 0,
      
      // Constellation
      constellationStarsCollected: 0,
      
      // Fire Skull
      fireSkullFlameIntensity: 1,
      
      // Chaos
      chaosDraggedUntil: 0,
      
      // Spore
      sporeCount: 0,
    };

    const mockGame = {
      simTime: 0,
      balance: BALANCE,
      balls: [mockBall],
      width: 96,
      height: 96,
      jokerThreads: [],
      fishingLines: []
    };

    if (drawBallProxyRef && drawBallProxyRef.current) {
      ctx.save();
      // Scale down to fit nicely in 96x96 canvas
      const targetRadius = 28;
      const scale = targetRadius / ballRadius;
      
      ctx.translate(48, 48);
      ctx.scale(scale, scale);
      ctx.translate(-48, -48);
      
      drawBallProxyRef.current(ctx, mockGame, mockBall, 0);
      
      ctx.restore();
    } else {
      // Fallback: draw a basic circle
      ctx.save();
      ctx.beginPath();
      ctx.arc(48, 48, 28, 0, Math.PI * 2);
      ctx.fillStyle = color || "#cbd5e1";
      ctx.fill();
      ctx.lineWidth = 4;
      ctx.strokeStyle = stroke || "#94a3b8";
      ctx.stroke();
      ctx.restore();
    }
  }, [type, color, stroke, proxyReady]);

  return (
    <canvas 
      ref={canvasRef} 
      width={96} 
      height={96} 
      className="w-24 h-24 block shrink-0 select-none rounded-2xl bg-slate-950/80 border border-slate-800/60 shadow-inner overflow-hidden"
    />
  );
};

