      ctx.bezierCurveTo(117, 310, 84, 270, 80, 185);
      ctx.bezierCurveTo(74, 205, 67, 225, 46, 235);
      ctx.closePath();
      ctx.fillStyle = hairGrad;
      ctx.fill();
      ctx.strokeStyle = "#050505";
      ctx.lineWidth = 7;
      ctx.stroke();

      // hair center part
      ctx.beginPath();
