      ctx.beginPath();
      ctx.moveTo(427, 290);
      ctx.bezierCurveTo(377, 340, 322, 370, 267, 378);
      ctx.lineTo(296, 438);
      ctx.bezierCurveTo(347, 410, 392, 365, 427, 290);
      ctx.closePath();
      ctx.fillStyle = shirtGrad;
      ctx.fill();
      ctx.strokeStyle = "#111";
      ctx.lineWidth = 6;
      ctx.stroke();

      // collar shadows
      ctx.beginPath();
      ctx.moveTo(218, 380);
      ctx.lineTo(246, 378);
      ctx.lineTo(226, 438);
      ctx.closePath();
      ctx.fillStyle = "rgba(156, 156, 156, 0.6)";
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(294, 380);
      ctx.lineTo(266, 378);
      ctx.lineTo(286, 438);
      ctx.closePath();
      ctx.fillStyle = "rgba(156, 156, 156, 0.6)";
      ctx.fill();

      // tie knot
      ctx.beginPath();
      ctx.moveTo(234, 372);
      ctx.lineTo(278, 372);
      ctx.lineTo(292, 395);
      ctx.lineTo(278, 418);
      ctx.lineTo(234, 418);
      ctx.lineTo(220, 395);
      ctx.closePath();
      ctx.fillStyle = "#141414";
      ctx.strokeStyle = "#050505";
      ctx.lineWidth = 6;
      ctx.fill();
      ctx.stroke();

      // tie
      ctx.beginPath();
      ctx.moveTo(238, 414);
      ctx.lineTo(274, 414);
      ctx.lineTo(290, 485);
      ctx.lineTo(256, 504);
      ctx.lineTo(222, 485);
      ctx.closePath();
      ctx.fillStyle = "#111";
      ctx.strokeStyle = "#050505";
      ctx.lineWidth = 6;
      ctx.fill();
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(256, 420);
      ctx.lineTo(256, 485);
      ctx.strokeStyle = "#222";
      ctx.lineWidth = 4;
      ctx.stroke();

      // suit lower shape
      ctx.beginPath();
      ctx.moveTo(75, 304);
      ctx.bezierCurveTo(115, 410, 175, 480, 256, 485);
      ctx.bezierCurveTo(337, 480, 397, 410, 437, 304);
