      ctx.bezierCurveTo(178, 420, 117, 365, 75, 304);
      ctx.closePath();
      ctx.fillStyle = "rgba(6, 6, 6, 0.55)";
      ctx.fill();

      // highlights
      ctx.beginPath();
      ctx.moveTo(110, 420);
      ctx.bezierCurveTo(150, 470, 210, 492, 256, 492);
      ctx.strokeStyle = "rgba(28, 28, 28, 0.8)";
      ctx.lineWidth = 5;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(125, 132);
      ctx.bezierCurveTo(150, 85, 200, 65, 238, 70);
      ctx.strokeStyle = "rgba(51, 51, 51, 0.7)";
      ctx.lineWidth = 4;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(392, 132);
      ctx.bezierCurveTo(362, 82, 310, 65, 276, 70);
      ctx.strokeStyle = "rgba(51, 51, 51, 0.7)";
      ctx.lineWidth = 4;
      ctx.stroke();

      ctx.restore();

      // Save context to draw rotated gun barrels on top
      ctx.save();
      ctx.translate(ball.x, ball.y);
      ctx.rotate(ball.angle);
      
      // Gun base connector (fixed pointing to the target)
